/**
 * Parser and types for `frontend/public/table/faces.json`.
 *
 * The manifest is generated by `tools/render/scripts/bake-faces.mjs`; it lists
 * the 38 faces, the glyph PNG (if any), the upstream provenance, and the
 * measured ink statistics of each committed PNG. Runtime composition needs only
 * `textureFile` and whether the asset has ink, but the rest is kept so the
 * atlas can report where its art came from.
 */
import { TILE_FACE_IDS, isTileFaceId } from './tiles';
import type { TileFaceId } from './tiles';

export interface FaceGlyphStats {
  readonly textureFile: string | null;
  /** Vendored source SVG under `tools/render/`, or null for the blank face. */
  readonly sourceSvg: string | null;
  /** Path in the pinned upstream repository, or null for the blank face. */
  readonly upstreamPath: string | null;
  readonly kind: 'number' | 'honour' | 'blank';
  readonly suit?: 'man' | 'pin' | 'sou';
  readonly rank?: number;
  readonly red?: boolean;
  readonly honour?: string;
  readonly bytes?: number;
  readonly measured: {
    readonly width: number;
    readonly height: number;
    readonly inkPixels: number;
    readonly inkFraction: number;
    readonly opaquePixels: number;
    readonly redPixels: number;
    readonly inkBBox: {
      readonly left: number;
      readonly top: number;
      readonly right: number;
      readonly bottom: number;
    } | null;
  } | null;
}

export interface FacesManifest {
  readonly version: number;
  readonly generatedBy: string;
  readonly source: {
    readonly repo: string;
    readonly commit: string;
    readonly license: string;
  };
  readonly raster: {
    readonly width: number;
    readonly height: number;
    readonly format: string;
  };
  readonly budgetBytes: number;
  readonly faces: Readonly<Record<TileFaceId, FaceGlyphStats>>;
}

function fail(message: string): never {
  throw new Error(`faces.json: ${message}`);
}

function finite(value: unknown, field: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) fail(`${field} must be a finite number`);
  return value;
}

function parseFace(id: TileFaceId, raw: unknown): FaceGlyphStats {
  if (typeof raw !== 'object' || raw === null) fail(`${id} must be an object`);
  const face = raw as Record<string, unknown>;
  const kind = face.kind;
  if (kind !== 'number' && kind !== 'honour' && kind !== 'blank') {
    fail(`${id}.kind must be number, honour or blank`);
  }
  const textureFile = face.textureFile;
  if (textureFile !== null && (typeof textureFile !== 'string' || !textureFile)) {
    fail(`${id}.textureFile must be a path or null`);
  }
  const measuredRaw = face.measured;
  let measured: FaceGlyphStats['measured'] = null;
  if (measuredRaw !== null && measuredRaw !== undefined) {
    if (typeof measuredRaw !== 'object') fail(`${id}.measured must be an object`);
    const m = measuredRaw as Record<string, unknown>;
    const bboxRaw = m.inkBBox;
    let inkBBox: NonNullable<FaceGlyphStats['measured']>['inkBBox'] = null;
    if (bboxRaw !== null && bboxRaw !== undefined) {
      if (typeof bboxRaw !== 'object') fail(`${id}.measured.inkBBox must be an object or null`);
      const b = bboxRaw as Record<string, unknown>;
      inkBBox = {
        left: finite(b.left, `${id}.measured.inkBBox.left`),
        top: finite(b.top, `${id}.measured.inkBBox.top`),
        right: finite(b.right, `${id}.measured.inkBBox.right`),
        bottom: finite(b.bottom, `${id}.measured.inkBBox.bottom`),
      };
    }
    measured = {
      width: finite(m.width, `${id}.measured.width`),
      height: finite(m.height, `${id}.measured.height`),
      inkPixels: finite(m.inkPixels, `${id}.measured.inkPixels`),
      inkFraction: finite(m.inkFraction, `${id}.measured.inkFraction`),
      opaquePixels: finite(m.opaquePixels, `${id}.measured.opaquePixels`),
      redPixels: finite(m.redPixels, `${id}.measured.redPixels`),
      inkBBox,
    };
  }
  if (textureFile && !measured) fail(`${id} has a textureFile but no measured stats`);

  return {
    textureFile,
    sourceSvg: typeof face.sourceSvg === 'string' ? face.sourceSvg : null,
    upstreamPath: typeof face.upstreamPath === 'string' ? face.upstreamPath : null,
    kind,
    suit:
      face.suit === 'man' || face.suit === 'pin' || face.suit === 'sou' ? face.suit : undefined,
    rank: typeof face.rank === 'number' ? face.rank : undefined,
    red: face.red === true,
    honour: typeof face.honour === 'string' ? face.honour : undefined,
    bytes: typeof face.bytes === 'number' ? face.bytes : undefined,
    measured,
  };
}

/** True when the committed glyph has visible ink on it. */
export function faceHasInk(face: FaceGlyphStats): boolean {
  // Haku (5z) upstream is a blank white dragon: its symbol-only SVG rasterises
  // to a fully transparent PNG, exactly like `blank`. Both are drawn as the
  // bare ivory shell rather than a second identical atlas slot.
  return Boolean(face.textureFile) && (face.measured?.inkPixels ?? 0) > 0;
}

/** Parse and validate a decoded `faces.json`. */
export function parseFacesManifest(raw: unknown): FacesManifest {
  if (typeof raw !== 'object' || raw === null) fail('document must be an object');
  const doc = raw as Record<string, unknown>;
  if (doc.version !== 1) fail(`version must be 1, got ${String(doc.version)}`);
  if (typeof doc.source !== 'object' || doc.source === null) fail('source must be an object');
  if (typeof doc.raster !== 'object' || doc.raster === null) fail('raster must be an object');
  if (typeof doc.faces !== 'object' || doc.faces === null) fail('faces must be an object');
  const source = doc.source as Record<string, unknown>;
  const raster = doc.raster as Record<string, unknown>;
  const facesRaw = doc.faces as Record<string, unknown>;
  const ids = Object.keys(facesRaw);
  if (ids.length !== TILE_FACE_IDS.length) {
    fail(`expected ${TILE_FACE_IDS.length} faces, got ${ids.length}`);
  }
  const faces = {} as Record<TileFaceId, FaceGlyphStats>;
  for (const id of ids) {
    if (!isTileFaceId(id)) fail(`unknown face ${id}`);
    faces[id] = parseFace(id, facesRaw[id]);
  }
  for (const id of TILE_FACE_IDS) {
    if (!faces[id]) fail(`missing face ${id}`);
  }
  const budget = doc.budget;
  if (typeof budget !== 'object' || budget === null) fail('budget must be an object');
  return {
    version: 1,
    generatedBy: typeof doc.generatedBy === 'string' ? doc.generatedBy : '',
    source: {
      repo: typeof source.repo === 'string' ? source.repo : '',
      commit: typeof source.commit === 'string' ? source.commit : '',
      license: typeof source.license === 'string' ? source.license : '',
    },
    raster: {
      width: finite(raster.width, 'raster.width'),
      height: finite(raster.height, 'raster.height'),
      format: typeof raster.format === 'string' ? raster.format : '',
    },
    budgetBytes: finite((budget as Record<string, unknown>).bytes, 'budget.bytes'),
    faces,
  };
}
